#!/usr/bin/env bash
# Install CrossRun for the current user (no system files are modified).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PREFIX="${PREFIX:-$HOME/.local}"
BIN_DIR="$PREFIX/bin"
APPLICATIONS="$PREFIX/share/applications"
ICONS="$PREFIX/share/icons/hicolor/scalable/apps"

mkdir -p "$BIN_DIR" "$APPLICATIONS" "$ICONS"

write_wrapper() {
    local name="$1"
    local module="$2"
    local target="$BIN_DIR/$name"
    cat > "$target" <<EOF
#!/bin/sh
# Generated by CrossRun's install.sh
export PYTHONPATH="$ROOT\${PYTHONPATH:+:\$PYTHONPATH}"
exec python3 -m $module "\$@"
EOF
    chmod 755 "$target"
    echo "installed $target"
}

write_wrapper crossrun crossrun
write_wrapper crossrun-gui crossrun.gui

sed "s|@EXEC@|\"$BIN_DIR/crossrun\" gui|" "$ROOT/assets/crossrun.desktop" \
    > "$APPLICATIONS/crossrun.desktop"
cp "$ROOT/assets/crossrun.svg" "$ICONS/crossrun.svg"

if command -v update-desktop-database >/dev/null 2>&1; then
    update-desktop-database "$APPLICATIONS" >/dev/null 2>&1 || true
fi
if command -v gtk-update-icon-cache >/dev/null 2>&1; then
    gtk-update-icon-cache -f -t "$PREFIX/share/icons/hicolor" >/dev/null 2>&1 || true
fi

echo
echo "CrossRun installed."
echo "  CLI: $BIN_DIR/crossrun"
echo "  GUI: $BIN_DIR/crossrun-gui (or the CrossRun menu entry)"
echo
if ! printf '%s' ":$PATH:" | grep -q ":$BIN_DIR:"; then
    echo "Note: $BIN_DIR is not on your PATH. Add it with:"
    echo "  export PATH=\"$BIN_DIR:\$PATH\""
    echo
fi
echo "Next:"
echo "  crossrun doctor"
echo "  crossrun setup --backend both --with-libs"
echo "  crossrun selftest"
